/* Amstrad CPC 464 / 6128 + GX4000 (.sna, .dsk, .bin, .cpr): see cpc.h.
 * Zero static .bss footprint: all RAM, ROM, FDC/DSK, CPR and video buffers live in KSEG0(EMU_RAM_PHYS).
 */
#pragma GCC optimize("O2")
#include "cpc.h"
#include "z80.h"

#ifndef CPC_HOST
#include "hw.h"
#endif

#define CPC_MAX_DSK  0x100000u          /* up to 1 MB .dsk image */
#define CPC_MAX_CPR  (32u * 0x4000u)    /* up to 512 KB GX4000 .cpr (32 x 16 KB banks) */
#define CPC_RING_LEN 4096u
#define CPC_FB_W     768                /* 48 CCLKs * 16 hi-res pixels */
#define CPC_FB_H     272                /* visible CRT lines (v_pos 32..303) */

struct cpc_dsk_sec {
    u8 c, h, r, n, st1, st2;
    u16 data_size;
    u32 data_off;
};

struct cpc_dsk_trk {
    u8 num_secs;
    struct cpc_dsk_sec sec[32];
};

struct cpc_ws {
    u8 ram[8][0x4000];                  /* 128 KB CPC 6128 RAM (8 x 16 KB banks) */
    u8 rom_os[0x4000];                  /* 16 KB Lower OS ROM */
    u8 rom_basic[0x4000];               /* 16 KB Upper ROM 0 (Locomotive BASIC 1.1) */
    u8 rom_amsdos[0x4000];              /* 16 KB Upper ROM 7 (AMSDOS 0.5) */
    u8 fb[CPC_FB_W * CPC_FB_H];         /* 768x272 hw color indices (0..31, 32=black) */
    u8 line_mode[CPC_FB_H];             /* mode used per visible line (for dynamic Mode 2 hi-res) */
    s16 snd_ring[CPC_RING_LEN];
    u16 hw_pal[33];                     /* RGB15 (0bbbbbgggggrrrrr) */
    struct cpc_dsk_trk trk[2][84];      /* parsed .dsk sector directory (2 sides x 84 tracks) */
    u8 dsk_data[CPC_MAX_DSK];           /* .dsk image buffer */
    u8 cpr_banks[32][0x4000];           /* GX4000 / CPC+ .cpr 16 KB cartridge banks */
    u8 sav_dummy[16];
};

#ifdef CPC_HOST
static struct cpc_ws cpc_host_ws;
#define WS (&cpc_host_ws)
#else
#define WS ((struct cpc_ws *)KSEG0(EMU_RAM_PHYS))
#endif

#define RGB15_CPC(r, g, b) ((u16)((((r) >> 3) & 31u) | ((((g) >> 3) & 31u) << 5) | ((((b) >> 3) & 31u) << 10)))

