static struct {
    struct z80 cpu;

    /* Gate Array */
    u8 ga_inksel, ga_config, ga_border, ga_ink[16];
    u8 ga_mode, ga_ram_cfg, ga_rom_sel;
    u8 ga_hscount, ga_intcnt, ga_clkcnt, ga_sync, ga_prev_hs, ga_prev_vs;
    u8 ga_latch[2];

    /* CRT beam */
    s16 crt_x, crt_y, crt_hpos, crt_vpos, crt_hret, crt_vret, crt_sync_cnt;
    u8 crt_vis, crt_sync, crt_hblank, crt_vblank;

    /* UM6845R CRTC */
    u8 crtc_sel, crtc_reg[32];
    u8 h_ctr, hsync_ctr, v_ctr, r_ctr, vsync_ctr;
    u16 ma, ma_row_start, ma_store;
    u8 hs, vs, h_de, v_de;
    u8 co_htotal, co_hdisp, co_hspos, co_hswidth;
    u8 co_vtotal, co_vdisp, co_vspos, co_vswidth, co_raster;

    /* 8255 PPI */
    u8 ppi_pa, ppi_pb, ppi_pc, ppi_ctrl;

    /* AY-3-8912 PSG (1 MHz clock) */
    u8 psg_sel, psg_latch, psg_reg[16];
    u32 psg_phase[3], psg_nphase, psg_ephase, psg_lfsr;
    u8 psg_out[3], psg_estep, psg_evol, psg_ehold, psg_eatt;
    s32 psg_dc;

    /* Keyboard (10 columns x 8 bits, active-high 1=pressed before inversion) */
    u8 kbd_hid[10], kbd_joy[10], kbd_auto[10];
    char type_q[256];
    u8 type_head, type_tail, type_hold, type_gap;
    u16 boot_delay;

    /* uPD765 FDC + .dsk */
    u8 has_dsk, dsk_sides, dsk_tracks, dsk_motor, dsk_dirty;
    u32 dsk_size;
    u8 fdc_phase, fdc_cmd, fdc_fpos, fdc_fnum, fdc_fifo[16];
    u8 fdc_st[4], fdc_phys_trk, fdc_side, fdc_cur_sec, fdc_eot;
    u8 fdc_c, fdc_h, fdc_r, fdc_n;
    u16 fdc_bpos, fdc_blen;
    u32 fdc_doff;
    u8 fdc_writing;

    /* GX4000 / CPC+ .cpr */
    u8 has_cpr, cpr_num_banks;

    /* Output geometry & audio */
    int out_w, out_h;
    u32 snd_hz, snd_acc, snd_head, snd_count;
    char info[96];
} S;

static void cpc_zero(void *dst, u32 n)
{
    u8 *p = (u8 *)dst;
    for (u32 i = 0; i < n; i++) p[i] = 0;
}

static void cpc_copy(void *dst, const void *src, u32 n)
{
    u8 *d = (u8 *)dst;
    const u8 *s = (const u8 *)src;
    for (u32 i = 0; i < n; i++) d[i] = s[i];
}

static void put_s(char **p, const char *end, const char *s)
{
    while (*s && *p < end) *(*p)++ = *s++;
    **p = 0;
}

static void put_u(char **p, const char *end, u32 v)
{
    char d[12]; int n = 0;
    do d[n++] = (char)('0' + (v % 10u)); while (v /= 10u);
    while (n && *p < end) *(*p)++ = d[--n];
    **p = 0;
}

/* ---- Memory Banking (1 KB pages directly wired into z80.c!) ---- */
static void update_banks(void)
{
    u8 cfg = S.ga_ram_cfg & 7u;
    u8 i0 = cpc_ram_map[cfg][0];
    u8 i1 = cpc_ram_map[cfg][1];
    u8 i2 = cpc_ram_map[cfg][2];
    u8 i3 = cpc_ram_map[cfg][3];

    u8 *lo_rom = S.has_cpr ? WS->cpr_banks[0] : WS->rom_os;
    u8 *hi_rom = WS->rom_basic;
    if (S.has_cpr && (S.ga_rom_sel & 0x80u))
        hi_rom = WS->cpr_banks[S.ga_rom_sel & 0x1Fu];
    else if (S.ga_rom_sel == 7u)
        hi_rom = WS->rom_amsdos;
    else if (S.has_cpr && S.ga_rom_sel > 0u && S.ga_rom_sel < 32u)
        hi_rom = WS->cpr_banks[S.ga_rom_sel];

    u8 *r0 = (S.ga_config & 0x04u) ? WS->ram[i0] : lo_rom;
    u8 *r1 = WS->ram[i1];
    u8 *r2 = WS->ram[i2];
    u8 *r3 = (S.ga_config & 0x08u) ? WS->ram[i3] : hi_rom;

    for (int p = 0; p < 16; p++) {
        u32 off = (u32)p << 10;
        S.cpu.rd[p]      = r0 + off;
        S.cpu.wr[p]      = WS->ram[i0] + off;
        S.cpu.rd[16 + p] = r1 + off;
        S.cpu.wr[16 + p] = WS->ram[i1] + off;
        S.cpu.rd[32 + p] = r2 + off;
        S.cpu.wr[32 + p] = WS->ram[i2] + off;
        S.cpu.rd[48 + p] = r3 + off;
        S.cpu.wr[48 + p] = WS->ram[i3] + off;
    }
}

static void cpc_irq_ack(struct z80 *c)
{
    c->irq = 0;
    S.ga_intcnt &= 0x1Fu;               /* Gate Array clears bit 5 of intcnt on INT ack */
}

/* ---- AY-3-8912 PSG + Keyboard Scan ---- */
static void psg_write_reg(u8 r, u8 v)
{
    static const u8 masks[16] = {
        0xFF,0x0F,0xFF,0x0F,0xFF,0x0F,0x1F,0xFF,
        0x1F,0x1F,0x1F,0xFF,0xFF,0x0F,0xFF,0xFF
    };
    r &= 15u;
    S.psg_reg[r] = v & masks[r];
    if (r == 13u) {
        S.psg_estep = 0;
        S.psg_ehold = 0;
        S.psg_eatt = (v & 0x04u) ? 1u : 0u;
        S.psg_evol = S.psg_eatt ? 0u : 15u;
        S.psg_ephase = 0;
    }
}

static u8 psg_read_reg(u8 r)
{
    r &= 15u;
    if (r == 14u) {
        u8 col = S.ppi_pc & 0x0Fu;
        if (col < 10u)
            return (u8)~(S.kbd_hid[col] | S.kbd_joy[col] | S.kbd_auto[col]);
        return 0xFFu;
    }
    return S.psg_reg[r];
}

static void psg_bus_update(void)
{
    u8 bdir_bc1 = (S.ppi_pc >> 6) & 3u;
    switch (bdir_bc1) {
    case 1:                             /* Read from PSG into PPI Port A input */
        if (S.ppi_ctrl & 0x10u)         /* PPI Port A in input mode */
            S.psg_latch = psg_read_reg(S.psg_sel);
        break;
    case 2:                             /* Write to PSG from PPI Port A */
        if (!(S.ppi_ctrl & 0x10u))
            psg_write_reg(S.psg_sel, S.ppi_pa);
        break;
    case 3:                             /* Latch PSG register address */
        S.psg_sel = (S.ppi_ctrl & 0x10u) ? (S.psg_latch & 15u) : (S.ppi_pa & 15u);
        break;
    }
}

/* Step AY-3-8912 by `cclk` 1-MHz ticks (PSG internal divider is /8 -> 125 kHz) */
static void psg_step_sample(u32 cclk_dt)
{
    for (int ch = 0; ch < 3; ch++) {
        u32 per = ((u32)S.psg_reg[ch * 2] | ((u32)S.psg_reg[ch * 2 + 1] << 8)) * 8u;
        if (per < 8u) per = 8u;
        S.psg_phase[ch] += cclk_dt;
        while (S.psg_phase[ch] >= per) {
            S.psg_phase[ch] -= per;
            S.psg_out[ch] ^= 1u;
        }
    }
    u32 nper = (u32)(S.psg_reg[6] ? S.psg_reg[6] : 1u) * 16u;
    S.psg_nphase += cclk_dt;
    while (S.psg_nphase >= nper) {
        S.psg_nphase -= nper;
        u32 bit = ((S.psg_lfsr ^ (S.psg_lfsr >> 3)) & 1u);
        S.psg_lfsr = (S.psg_lfsr >> 1) | (bit << 16);
    }
    u32 eper = ((u32)S.psg_reg[11] | ((u32)S.psg_reg[12] << 8)) * 16u;
    if (eper < 16u) eper = 16u;
    S.psg_ephase += cclk_dt;
    while (S.psg_ephase >= eper) {
        S.psg_ephase -= eper;
        if (!S.psg_ehold) {
            S.psg_estep++;
            if (S.psg_estep >= 16u) {
                S.psg_estep = 0;
                u8 sh = S.psg_reg[13];
                if (!(sh & 0x08u)) {
                    S.psg_evol = 0;
                    S.psg_ehold = 1;
                } else {
                    if (sh & 0x02u) S.psg_eatt ^= 1u;
                    if (sh & 0x01u) {
                        S.psg_ehold = 1;
                        S.psg_evol = S.psg_eatt ? 15u : 0u;
                        break;
                    }
                }
            }
            S.psg_evol = S.psg_eatt ? S.psg_estep : (u8)(15u - S.psg_estep);
        }
    }

    u8 mix = S.psg_reg[7];
    u8 nbit = (u8)(S.psg_lfsr & 1u);
    s32 sum = 0;
    for (int ch = 0; ch < 3; ch++) {
        u8 t_en = (mix >> ch) & 1u;
        u8 n_en = (mix >> (ch + 3)) & 1u;
        u8 gate = (S.psg_out[ch] | t_en) & (nbit | n_en);
        u8 vr = S.psg_reg[8 + ch];
        u8 v = (vr & 0x10u) ? S.psg_evol : (vr & 0x0Fu);
        if (gate)
            sum += ay_vol[v];
    }
    S.psg_dc += (sum - S.psg_dc) >> 8;
    s32 out = sum - S.psg_dc;
    if (out > 32767) out = 32767;
    if (out < -32768) out = -32768;
    if (S.snd_count < CPC_RING_LEN) {
        WS->snd_ring[(S.snd_head + S.snd_count) % CPC_RING_LEN] = (s16)out;
        S.snd_count++;
    }
}

/* ---- NEC uPD765 FDC (.dsk standard & extended) ---- */
enum { FDC_IDLE = 0, FDC_CMD = 1, FDC_EXEC = 2, FDC_RES = 3 };

static int fdc_find_sector(u8 side, u8 trk, u8 c, u8 h, u8 r)
{
    if (!S.has_dsk || side >= S.dsk_sides || trk >= S.dsk_tracks)
        return -1;
    const struct cpc_dsk_trk *t = &WS->trk[side][trk];
    for (int i = 0; i < t->num_secs; i++) {
        if (t->sec[i].r == r && t->sec[i].c == c && t->sec[i].h == h)
            return i;
    }
    for (int i = 0; i < t->num_secs; i++) {
        if (t->sec[i].r == r)
            return i;
    }
    return -1;
}

static void fdc_to_result7(void)
{
    S.fdc_phase = FDC_RES;
    S.fdc_fpos = 0;
    S.fdc_fnum = 7;
    S.fdc_fifo[0] = S.fdc_st[0];
    S.fdc_fifo[1] = S.fdc_st[1];
    S.fdc_fifo[2] = S.fdc_st[2];
    S.fdc_fifo[3] = S.fdc_c;
    S.fdc_fifo[4] = S.fdc_h;
    S.fdc_fifo[5] = S.fdc_r;
    S.fdc_fifo[6] = S.fdc_n;
}

static int fdc_setup_sector(void)
{
    int idx = fdc_find_sector(S.fdc_side, S.fdc_phys_trk, S.fdc_c, S.fdc_h, S.fdc_r);
    if (idx < 0) {
        S.fdc_st[0] |= 0x40u;           /* Abnormal termination */
        S.fdc_st[1] |= 0x04u;           /* No data */
        return 0;
    }
    const struct cpc_dsk_sec *sc = &WS->trk[S.fdc_side][S.fdc_phys_trk].sec[idx];
    S.fdc_c = sc->c;
    S.fdc_h = sc->h;
    S.fdc_r = sc->r;
    S.fdc_n = sc->n;
    S.fdc_st[1] = (u8)(sc->st1 & ~0x80u);
    S.fdc_st[2] = sc->st2;
    S.fdc_doff = sc->data_off;
    u16 want = (S.fdc_n == 0 && S.fdc_fifo[8] != 0xFFu) ? S.fdc_fifo[8] : sc->data_size;
    if (want == 0 || want > sc->data_size)
        want = sc->data_size;
    S.fdc_bpos = 0;
    S.fdc_blen = want;
    return 1;
}

static void fdc_exec_cmd(void)
{
    u8 cmd = S.fdc_cmd;
    switch (cmd) {
    case 0x06:                          /* READ DATA */
    case 0x0C:                          /* READ DELETED DATA */
    case 0x05:                          /* WRITE DATA */
    case 0x09: {                        /* WRITE DELETED DATA */
        u8 drv = S.fdc_fifo[1] & 3u;
        S.fdc_side = (S.fdc_fifo[1] >> 2) & 1u;
        S.fdc_st[0] = S.fdc_fifo[1] & 7u;
        S.fdc_st[1] = 0;
        S.fdc_st[2] = 0;
        S.fdc_c = S.fdc_fifo[2];
        S.fdc_h = S.fdc_fifo[3];
        S.fdc_r = S.fdc_fifo[4];
        S.fdc_n = S.fdc_fifo[5];
        S.fdc_eot = S.fdc_fifo[6];
        S.fdc_writing = (cmd == 0x05 || cmd == 0x09) ? 1u : 0u;
        if (drv != 0 || !S.has_dsk || !S.dsk_motor) {
            S.fdc_st[0] |= 0x48u;       /* AT + Not Ready */
            fdc_to_result7();
            return;
        }
        if (fdc_setup_sector()) {
            S.fdc_phase = FDC_EXEC;
        } else {
            fdc_to_result7();
        }
        break;
    }
    case 0x02: {                        /* READ A TRACK */
        u8 drv = S.fdc_fifo[1] & 3u;
        S.fdc_side = (S.fdc_fifo[1] >> 2) & 1u;
        S.fdc_st[0] = S.fdc_fifo[1] & 7u;
        S.fdc_st[1] = 0; S.fdc_st[2] = 0;
        if (drv != 0 || !S.has_dsk || !S.dsk_motor ||
            WS->trk[S.fdc_side][S.fdc_phys_trk].num_secs == 0) {
            S.fdc_st[0] |= 0x48u;
            fdc_to_result7();
            return;
        }
        const struct cpc_dsk_sec *sc = &WS->trk[S.fdc_side][S.fdc_phys_trk].sec[0];
        S.fdc_c = sc->c; S.fdc_h = sc->h; S.fdc_r = sc->r; S.fdc_n = sc->n;
        S.fdc_eot = sc->r;
        S.fdc_writing = 0;
        S.fdc_doff = sc->data_off;
        S.fdc_bpos = 0;
        S.fdc_blen = sc->data_size;
        S.fdc_phase = FDC_EXEC;
        break;
    }
    case 0x0A: {                        /* READ ID */
        u8 drv = S.fdc_fifo[1] & 3u;
        u8 side = (S.fdc_fifo[1] >> 2) & 1u;
        S.fdc_st[0] = S.fdc_fifo[1] & 7u;
        S.fdc_st[1] = 0; S.fdc_st[2] = 0;
        if (drv == 0 && S.has_dsk && S.dsk_motor &&
            side < S.dsk_sides && S.fdc_phys_trk < S.dsk_tracks &&
            WS->trk[side][S.fdc_phys_trk].num_secs > 0) {
            const struct cpc_dsk_trk *t = &WS->trk[side][S.fdc_phys_trk];
            u8 idx = S.fdc_cur_sec % t->num_secs;
            S.fdc_cur_sec = (u8)((idx + 1u) % t->num_secs);
            S.fdc_c = t->sec[idx].c;
            S.fdc_h = t->sec[idx].h;
            S.fdc_r = t->sec[idx].r;
            S.fdc_n = t->sec[idx].n;
        } else {
            S.fdc_st[0] |= 0x48u;
            S.fdc_st[1] |= 0x05u;
        }
        fdc_to_result7();
        break;
    }
    case 0x07: {                        /* RECALIBRATE */
        u8 drv = S.fdc_fifo[1] & 3u;
        if (drv == 0 && S.has_dsk) {
            S.fdc_phys_trk = 0;
            S.fdc_st[0] = 0x20u;        /* Seek End */
        } else {
            S.fdc_st[0] = 0x68u | drv;  /* AT + SE + NR */
        }
        S.fdc_phase = FDC_IDLE;
        break;
    }
    case 0x0F: {                        /* SEEK */
        u8 drv = S.fdc_fifo[1] & 3u;
        u8 ncn = S.fdc_fifo[2];
        if (drv == 0 && S.has_dsk) {
            S.fdc_phys_trk = ncn < S.dsk_tracks ? ncn : (u8)(S.dsk_tracks ? S.dsk_tracks - 1u : 0u);
            S.fdc_st[0] = 0x20u | (S.fdc_fifo[1] & 7u);
        } else {
            S.fdc_st[0] = 0x68u | (S.fdc_fifo[1] & 7u);
        }
        S.fdc_phase = FDC_IDLE;
        break;
    }
    case 0x08:                          /* SENSE INTERRUPT STATUS */
        S.fdc_phase = FDC_RES;
        S.fdc_fpos = 0;
        S.fdc_fnum = 2;
        S.fdc_fifo[0] = S.fdc_st[0];
        S.fdc_fifo[1] = S.fdc_phys_trk;
        S.fdc_st[0] = 0x80u;            /* subsequent sense w/o seek returns IC */
        break;
    case 0x04: {                        /* SENSE DRIVE STATUS */
        u8 drv = S.fdc_fifo[1] & 3u;
        u8 st3 = S.fdc_fifo[1] & 7u;
        if (drv == 0 && S.has_dsk) {
            if (S.dsk_sides > 1) st3 |= 0x08u;
            if (S.fdc_phys_trk == 0) st3 |= 0x10u;
            if (S.dsk_motor) st3 |= 0x20u;
        }
        S.fdc_phase = FDC_RES;
        S.fdc_fpos = 0;
        S.fdc_fnum = 1;
        S.fdc_fifo[0] = st3;
        break;
    }
    case 0x03:                          /* SPECIFY */
        S.fdc_phase = FDC_IDLE;
        break;
    default:                            /* Invalid / unimplemented command */
        S.fdc_phase = FDC_RES;
        S.fdc_fpos = 0;
        S.fdc_fnum = 1;
        S.fdc_fifo[0] = 0x80u;
        break;
    }
}

static u8 fdc_read(u8 a0)
{
    if (a0 == 0) {                      /* Main Status Register ($FB7E) */
        u8 msr = 0x80u;                 /* RQM always ready */
        if (S.fdc_phase != FDC_IDLE)
            msr |= 0x10u;               /* CB (FDC Busy) */
        if (S.fdc_phase == FDC_EXEC) {
            msr |= 0x20u;               /* EXM (Execution / non-DMA) */
            if (!S.fdc_writing)
                msr |= 0x40u;           /* DIO: FDC -> CPU */
        } else if (S.fdc_phase == FDC_RES) {
            msr |= 0x40u;               /* DIO: FDC -> CPU */
        }
        return msr;
    }
    /* Data Register ($FB7F) */
    if (S.fdc_phase == FDC_EXEC && !S.fdc_writing) {
        u8 b = (S.fdc_doff + S.fdc_bpos < S.dsk_size) ? WS->dsk_data[S.fdc_doff + S.fdc_bpos] : 0;
        S.fdc_bpos++;
        if (S.fdc_bpos >= S.fdc_blen) {
            if (S.fdc_r < S.fdc_eot) {
                S.fdc_r++;
                if (!fdc_setup_sector()) {
                    fdc_to_result7();
                }
            } else {
                S.fdc_st[1] |= 0x80u;   /* End of Cylinder (standard uPD765 non-TC completion) */
                fdc_to_result7();
            }
        }
        return b;
    }
    if (S.fdc_phase == FDC_RES) {
        u8 b = S.fdc_fifo[S.fdc_fpos++];
        if (S.fdc_fpos >= S.fdc_fnum)
            S.fdc_phase = FDC_IDLE;
        return b;
    }
    return 0xFFu;
}

static void fdc_write(u8 a0, u8 val)
{
    if (!a0) return;
    if (S.fdc_phase == FDC_IDLE) {
        S.fdc_cmd = val & 0x1Fu;
        u8 n = 1;
        switch (S.fdc_cmd) {
        case 0x06: case 0x0C: case 0x05: case 0x09: case 0x02:
        case 0x11: case 0x19: case 0x1D: n = 9; break;
        case 0x0A: case 0x07: case 0x04: n = 2; break;
        case 0x0F: case 0x03:            n = 3; break;
        case 0x0D:                       n = 6; break;
        default:                         n = 1; break;
        }
        S.fdc_phase = FDC_CMD;
        S.fdc_fpos = 0;
        S.fdc_fnum = n;
        S.fdc_fifo[S.fdc_fpos++] = val;
        if (S.fdc_fpos >= S.fdc_fnum)
            fdc_exec_cmd();
    } else if (S.fdc_phase == FDC_CMD) {
        S.fdc_fifo[S.fdc_fpos++] = val;
        if (S.fdc_fpos >= S.fdc_fnum)
            fdc_exec_cmd();
    } else if (S.fdc_phase == FDC_EXEC && S.fdc_writing) {
        if (S.fdc_doff + S.fdc_bpos < S.dsk_size) {
            WS->dsk_data[S.fdc_doff + S.fdc_bpos] = val;
            S.dsk_dirty = 1;
        }
        S.fdc_bpos++;
        if (S.fdc_bpos >= S.fdc_blen) {
            if (S.fdc_r < S.fdc_eot) {
                S.fdc_r++;
                if (!fdc_setup_sector())
                    fdc_to_result7();
            } else {
                S.fdc_st[1] |= 0x80u;
                fdc_to_result7();
            }
        }
    }
}

/* ---- Z80 I/O Port Decoding ---- */
static void ga_write(u8 data)
{
    switch (data & 0xC0u) {
    case 0x00:
        S.ga_inksel = data & 0x1Fu;
        break;
    case 0x40:
        if (S.ga_inksel & 0x10u)
            S.ga_border = data & 0x1Fu;
        else
            S.ga_ink[S.ga_inksel & 15u] = data & 0x1Fu;
        break;
    case 0x80: {
        u8 diff = (S.ga_config ^ data) & 0x0Cu;
        S.ga_config = data & 0x1Fu;
        if (data & 0x10u) {             /* IRQ_RESET */
            S.ga_config &= ~0x10u;
            S.ga_intcnt = 0;
            S.cpu.irq = 0;
        }
        if (diff)
            update_banks();
        break;
    }
    case 0xC0:
        if ((S.ga_ram_cfg ^ data) & 7u) {
            S.ga_ram_cfg = data & 7u;
            update_banks();
        }
        break;
    }
}

static void crtc_cmp_h(void)
{
    if (S.h_ctr >= (u8)(S.crtc_reg[0] + 1u)) S.co_htotal = 1;
    if (S.h_ctr == S.crtc_reg[1]) S.co_hdisp = 1;
    if (S.h_ctr == S.crtc_reg[2]) S.co_hspos = 1;
}

static void crtc_cmp_v(void)
{
    if (S.v_ctr >= (u8)(S.crtc_reg[4] + 1u)) S.co_vtotal = 1;
    if (S.v_ctr == S.crtc_reg[6]) S.co_vdisp = 1;
    if (S.v_ctr == S.crtc_reg[7]) S.co_vspos = 1;
}

static void crtc_cmp_raster(void)
{
    u8 max_sl = S.crtc_reg[9];
    if (S.v_ctr == S.crtc_reg[4])
        max_sl = (u8)(max_sl + S.crtc_reg[5]);
    if (S.r_ctr >= (u8)(max_sl + 1u))
        S.co_raster = 1;
}

static u8 cpc_io_in(struct z80 *c, u16 port)
{
    c->cycles += 4;                     /* CPC Gate Array stretches I/O cycles to 4 NOPs (16T) */
    u8 val = 0xFFu;

    /* i8255 PPI (~A11 == 0) */
    if (!(port & 0x0800u)) {
        switch ((port >> 8) & 3u) {
        case 0:                         /* Port A */
            psg_bus_update();
            val = (S.ppi_ctrl & 0x10u) ? S.psg_latch : S.ppi_pa;
            break;
        case 1:                         /* Port B: VSync (bit0), Amstrad ID (bits 3..1=7), 50Hz (bit4=1), /EXP (bit5=1) */
            val = (S.ppi_ctrl & 0x02u)
                ? (u8)(0x3Eu | (S.vs ? 1u : 0u))
                : S.ppi_pb;
            break;
        case 2:                         /* Port C */
            val = S.ppi_pc;
            break;
        case 3:
            val = 0xFFu;
            break;
        }
    }

    /* Gate Array also triggers on IN when A15=0, A14=1! */
    if ((port & 0xC000u) == 0x4000u)
        ga_write(val);

    /* MC6845 CRTC (~A14 == 0, RW=A9=1) */
    if (!(port & 0x4000u) && (port & 0x0200u)) {
        if (port & 0x0100u) {
            u8 r = S.crtc_sel & 0x1Fu;
            if (r == 14u || r == 15u || r == 16u || r == 17u || r == 31u)
                val = S.crtc_reg[r] & crtc_mask[r];
            else
                val = 0;
        } else {
            val = S.v_de ? 0x00u : 0x20u; /* UM6845R status: bit 5 = VBlank */
        }
    }

    /* uPD765 FDC ($FB7E / $FB7F: A10=0, A8=1, A7=0) */
    if ((port & 0x0580u) == 0x0100u)
        val = fdc_read((u8)(port & 1u));

    return val;
}

static void cpc_io_out(struct z80 *c, u16 port, u8 val)
{
    c->cycles += 4;                     /* CPC Gate Array stretches I/O cycles to 4 NOPs (16T) */

    /* Gate Array (A15=0, A14=1) & PAL16L8 128K RAM banking (A15=0, val & 0xC0 == 0xC0) */
    if ((port & 0xC000u) == 0x4000u) {
        ga_write(val);
    } else if (!(port & 0x8000u) && (val & 0xC0u) == 0xC0u) {
        if ((S.ga_ram_cfg ^ val) & 7u) {
            S.ga_ram_cfg = val & 7u;
            update_banks();
        }
    }

    /* Upper ROM select (~A13 == 0) */
    if (!(port & 0x2000u)) {
        if (S.ga_rom_sel != val) {
            S.ga_rom_sel = val;
            update_banks();
        }
    }

    /* MC6845 CRTC (~A14 == 0, RW=A9=0) */
    if ((port & 0x4200u) == 0x0000u) {
        if (port & 0x0100u) {
            u8 r = S.crtc_sel & 0x1Fu;
            if (r <= 15u) {
                S.crtc_reg[r] = val & crtc_mask[r];
                switch (r) {
                case 0: if (S.h_ctr >= (u8)(S.crtc_reg[0] + 1u)) S.co_htotal = 1; break;
                case 1: if (S.h_ctr == S.crtc_reg[1]) S.co_hdisp = 1; break;
                case 2: if (S.h_ctr == S.crtc_reg[2]) S.co_hspos = 1; break;
                case 3:
                    if (S.hsync_ctr == (S.crtc_reg[3] & 0x0Fu)) S.co_hswidth = 1;
                    if (S.vsync_ctr == 16u) S.co_vswidth = 1;
                    break;
                case 4: if (S.v_ctr >= (u8)(S.crtc_reg[4] + 1u)) S.co_vtotal = 1; break;
                case 6: if (S.v_ctr == S.crtc_reg[6]) S.co_vdisp = 1; break;
                case 7: if (S.v_ctr == S.crtc_reg[7]) S.co_vspos = 1; break;
                case 9: crtc_cmp_raster(); break;
                }
            }
        } else {
            S.crtc_sel = val & 0x1Fu;
        }
    }

    /* i8255 PPI (~A11 == 0) */
    if (!(port & 0x0800u)) {
        switch ((port >> 8) & 3u) {
        case 0:
            S.ppi_pa = val;
            psg_bus_update();
            break;
        case 1:
            S.ppi_pb = val;
            break;
        case 2:
            S.ppi_pc = val;
            psg_bus_update();
            break;
        case 3:
            if (val & 0x80u) {
                S.ppi_ctrl = val;
                S.ppi_pa = S.ppi_pb = S.ppi_pc = 0;
            } else {                    /* Bit set/reset on Port C */
                u8 bit = (val >> 1) & 7u;
                if (val & 1u) S.ppi_pc |= (u8)(1u << bit);
                else          S.ppi_pc &= (u8)~(1u << bit);
                psg_bus_update();
            }
            break;
        }
    }

    /* Floppy motor ($FA7E: A10=0, A8=0, A7=0) & uPD765 Data ($FB7F: A10=0, A8=1, A7=0) */
    if ((port & 0x0580u) == 0x0000u)
        S.dsk_motor = val & 1u;
    else if ((port & 0x0580u) == 0x0100u)
        fdc_write((u8)(port & 1u), val);
}

/* ---- Cycle-Exact 1 MHz CCLK: UM6845R CRTC + Amstrad 40010 Gate Array ---- */
static void cclk_step(void)
{
    /* 1. Step UM6845R CRTC (with hardware coincidence latches) */
    u16 prev_ma = S.ma;
    u8 prev_ra = S.r_ctr;
    u8 cur_de = (S.h_de && S.v_de) ? 1u : 0u;

    S.ma = (S.ma + 1u) & 0x3FFFu;
    S.h_ctr++;
    crtc_cmp_h();
    if (S.co_htotal) {
        S.co_htotal = 0;
        S.r_ctr = (S.r_ctr + 1u) & 0x1Fu;
        crtc_cmp_raster();
        if (S.co_raster) {
            S.co_raster = 0;
            S.r_ctr = 0;
            crtc_cmp_raster();
            S.v_ctr = (S.v_ctr + 1u) & 0x7Fu;
            crtc_cmp_v();
            if (S.co_vdisp) {
                S.co_vdisp = 0;
                S.v_de = 0;
            }
            if (S.co_vtotal) {
                S.co_vtotal = 0;
                S.v_ctr = 0;
                crtc_cmp_v();
                S.v_de = 1;
                if (S.co_vdisp) { S.co_vdisp = 0; S.v_de = 0; }
                S.ma_store = ((u16)S.crtc_reg[12] << 8) | S.crtc_reg[13];
            }
            if (S.co_vspos) {
                S.co_vspos = 0;
                S.vs = 1;
                S.vsync_ctr = 0;
            }
            S.ma_row_start = S.ma_store;
        }
        if (S.v_ctr == 0u) {
            S.ma_store = ((u16)S.crtc_reg[12] << 8) | S.crtc_reg[13];
            S.ma_row_start = S.ma_store;
        }
        if (S.vs) {
            if (S.vsync_ctr == 16u) S.co_vswidth = 1;
            S.vsync_ctr++;
            if (S.co_vswidth) {
                S.co_vswidth = 0;
                S.vs = 0;
            }
        }
        S.h_de = 1;
        S.h_ctr = 0;
        crtc_cmp_h();
        S.ma = S.ma_row_start;
    }
    if (S.co_hdisp) {
        S.co_hdisp = 0;
        S.h_de = 0;
        S.ma_store = S.ma;
    }
    if (S.co_hspos) {
        S.co_hspos = 0;
        S.hs = 1;
        S.hsync_ctr = 0;
    }
    if (S.hs) {
        if (S.hsync_ctr == (S.crtc_reg[3] & 0x0Fu)) S.co_hswidth = 1;
        S.hsync_ctr++;
        if (S.co_hswidth) {
            S.co_hswidth = 0;
            S.hs = 0;
        }
    }

    /* 2. Fetch 2 video RAM bytes from base 64 KB (ram[0..3]) */
    u16 vaddr = (u16)(((prev_ma & 0x3000u) << 2) | ((u16)(prev_ra & 7u) << 11) | ((prev_ma & 0x03FFu) << 1));
    const u8 *base64 = &WS->ram[0][0];
    S.ga_latch[0] = base64[vaddr];
    S.ga_latch[1] = base64[vaddr | 1u];

    /* 3. Gate Array SYNC, Mode latch & 52-line Interrupt Counter */
    u8 hs_fall = (!S.hs && S.ga_prev_hs) ? 1u : 0u;
    u8 vs_rise = (S.vs && !S.ga_prev_vs) ? 1u : 0u;
    S.ga_prev_hs = S.hs;
    S.ga_prev_vs = S.vs;

    if (vs_rise)
        S.ga_hscount = 0;
    if (hs_fall) {
        S.ga_intcnt = (S.ga_intcnt + 1u) & 0x3Fu;
        if (S.ga_hscount < 32u)
            S.ga_hscount++;
        if (S.ga_hscount == 2u) {
            if (S.ga_intcnt >= 32u)
                S.cpu.irq = 1;
            S.ga_intcnt = 0;
        }
        if (S.ga_intcnt == 52u) {
            S.cpu.irq = 1;
            S.ga_intcnt = 0;
        }
    }

    if (S.ga_clkcnt == 7u)
        S.ga_mode = S.ga_config & 3u;
    if (!S.hs)
        S.ga_clkcnt = 0;
    else if (S.ga_clkcnt < 8u)
        S.ga_clkcnt++;

    u8 v_sync = S.ga_hscount < 4u ? 1u : 0u;
    u8 h_sync = (S.ga_clkcnt > 2u && S.ga_clkcnt < 7u) ? 1u : 0u;
    u8 sync = v_sync | h_sync;

    /* 4. CRT Beam Tracking (48x272 visible window -> 768x272 hi-res pixels) */
    u8 sync_raise = (sync && !S.crt_sync) ? 1u : 0u;
    u8 new_line = 0, new_frame = 0;
    S.crt_sync = sync;
    if (sync) S.crt_sync_cnt++;
    if (sync_raise) {
        S.crt_hret = 7;
        S.crt_hblank = 1;
        S.crt_sync_cnt = 0;
    }
    if (S.crt_sync_cnt == 64) {
        S.crt_vret = 3;
        S.crt_vblank = 1;
    }
    S.crt_hpos++;
    if (S.crt_hpos == 6) S.crt_hblank = 0;
    else if (S.crt_hpos >= 64) new_line = 1;
    if (S.crt_hret > 0 && --S.crt_hret == 0) new_line = 1;
    if (new_line) {
        S.crt_hpos = 0;
        S.crt_vpos++;
        if (S.crt_vpos == 5) S.crt_vblank = 0;
        else if (S.crt_vpos >= 312) new_frame = 1;
        if (S.crt_vret > 0 && --S.crt_vret == 0) new_frame = 1;
    }
    if (new_frame)
        S.crt_vpos = 0;

    if (S.crt_hpos >= 6 && S.crt_hpos < 54 && S.crt_vpos >= 32 && S.crt_vpos < 304) {
        int px = (S.crt_hpos - 6) * 16;
        int py = S.crt_vpos - 32;
        u8 *dst = &WS->fb[py * CPC_FB_W + px];
        if (cur_de) {
            WS->line_mode[py] = S.ga_mode;
            switch (S.ga_mode) {
            case 0:
                for (int i = 0; i < 2; i++) {
                    u8 c = S.ga_latch[i];
                    u8 p0 = S.ga_ink[((c >> 7) & 1u) | ((c >> 2) & 2u) | ((c >> 3) & 4u) | ((c << 2) & 8u)];
                    u8 p1 = S.ga_ink[((c >> 6) & 1u) | ((c >> 1) & 2u) | ((c >> 2) & 4u) | ((c << 3) & 8u)];
                    dst[0]=dst[1]=dst[2]=dst[3]=p0;
                    dst[4]=dst[5]=dst[6]=dst[7]=p1;
                    dst += 8;
                }
                break;
            case 1:
                for (int i = 0; i < 2; i++) {
                    u8 c = S.ga_latch[i];
                    u8 p0 = S.ga_ink[((c >> 2) & 2u) | ((c >> 7) & 1u)];
                    u8 p1 = S.ga_ink[((c >> 1) & 2u) | ((c >> 6) & 1u)];
                    u8 p2 = S.ga_ink[((c >> 0) & 2u) | ((c >> 5) & 1u)];
                    u8 p3 = S.ga_ink[((c << 1) & 2u) | ((c >> 4) & 1u)];
                    dst[0]=dst[1]=p0; dst[2]=dst[3]=p1; dst[4]=dst[5]=p2; dst[6]=dst[7]=p3;
                    dst += 8;
                }
                break;
            case 2:
                for (int i = 0; i < 2; i++) {
                    u8 c = S.ga_latch[i];
                    for (int b = 7; b >= 0; b--)
                        *dst++ = S.ga_ink[(c >> b) & 1u];
                }
                break;
            default:
                for (int i = 0; i < 2; i++) {
                    u8 c = S.ga_latch[i];
                    u8 p0 = S.ga_ink[((c >> 7) & 1u) | ((c >> 2) & 2u)];
                    u8 p1 = S.ga_ink[((c >> 6) & 1u) | ((c >> 1) & 2u)];
                    dst[0]=dst[1]=dst[2]=dst[3]=p0;
                    dst[4]=dst[5]=dst[6]=dst[7]=p1;
                    dst += 8;
                }
                break;
            }
        } else {
            u8 bc = sync ? 32u : S.ga_border;
            for (int i = 0; i < 16; i++)
                dst[i] = bc;
        }
    }
}

/* ---- Keyboard Mapping (USB HID + UART/Auto-Type) ---- */
static void kbd_press_char(u8 mat[10], char ch)
{
    static const char *unshifted =
        "   ^08641 "
        "  [-97532 "
        "   @oure  "
        "  ]piytwq "
        "   ;lhgs  "
        "   :kjfda "
        "  \\/mnbc  "
        "   ., vxz ";
    static const char *shifted =
        "    _(&$! "
        "  {=)'%#\" "
        "   |OURE  "
        "  }PIYTWQ "
        "   +LHGS  "
        "   *KJFDA "
        "  `?MNBC  "
        "   >< VXZ ";

    if (ch == '\r' || ch == '\n') { mat[2] |= (1u << 2); return; }
    if (ch == ' ')  { mat[5] |= (1u << 7); return; }
    if (ch == 0x08 || ch == 0x7F) { mat[9] |= (1u << 7); return; }

    for (int sh = 0; sh < 2; sh++) {
        const char *m = sh ? shifted : unshifted;
        for (int line = 0; line < 8; line++) {
            for (int col = 0; col < 10; col++) {
                char mc = m[line * 10 + col];
                if (mc != ' ' && mc == ch) {
                    mat[col] |= (u8)(1u << line);
                    if (sh) mat[2] |= (1u << 5); /* Shift */
                    return;
                }
            }
        }
    }
}

void cpc_typed(char c)
{
    u8 next = (u8)((S.type_tail + 1u) % sizeof(S.type_q));
    if (next != S.type_head) {
        S.type_q[S.type_tail] = c;
        S.type_tail = next;
    }
}

static void queue_str(const char *s)
{
    while (*s) cpc_typed(*s++);
}

void cpc_keyboard(const u8 *usages, int n)
{
    cpc_zero(S.kbd_hid, sizeof(S.kbd_hid));
    int shift = 0, ctrl = 0;
    for (int i = 0; i < n; i++) {
        u8 u = usages[i];
        if (u == 0xE1 || u == 0xE5) shift = 1;
        if (u == 0xE0 || u == 0xE4) ctrl = 1;
    }
    if (shift) S.kbd_hid[2] |= (1u << 5);
    if (ctrl)  S.kbd_hid[2] |= (1u << 7);

    for (int i = 0; i < n; i++) {
        u8 u = usages[i];
        if (u >= 0x04 && u <= 0x1D) {
            char c = (char)((shift ? 'A' : 'a') + (u - 0x04));
            kbd_press_char(S.kbd_hid, c);
        } else if (u >= 0x1E && u <= 0x26) {
            static const char *s_num = "!\"#$%&'()";
            kbd_press_char(S.kbd_hid, shift ? s_num[u - 0x1E] : (char)('1' + (u - 0x1E)));
        } else if (u == 0x27) {
            kbd_press_char(S.kbd_hid, shift ? '_' : '0');
        } else {
            switch (u) {
            case 0x28: S.kbd_hid[2] |= (1u << 2); break; /* Return */
            case 0x2A: S.kbd_hid[9] |= (1u << 7); break; /* Backspace -> DEL */
            case 0x2C: S.kbd_hid[5] |= (1u << 7); break; /* Space */
            case 0x2D: kbd_press_char(S.kbd_hid, shift ? '=' : '-'); break;
            case 0x2E: kbd_press_char(S.kbd_hid, shift ? '+' : '^'); break;
            case 0x2F: kbd_press_char(S.kbd_hid, shift ? '|' : '@'); break;
            case 0x30: kbd_press_char(S.kbd_hid, shift ? '{' : '['); break;
            case 0x33: kbd_press_char(S.kbd_hid, shift ? '+' : ';'); break;
            case 0x34: kbd_press_char(S.kbd_hid, shift ? '*' : ':'); break;
            case 0x36: kbd_press_char(S.kbd_hid, shift ? '<' : ','); break;
            case 0x37: kbd_press_char(S.kbd_hid, shift ? '>' : '.'); break;
            case 0x38: kbd_press_char(S.kbd_hid, shift ? '?' : '/'); break;
            case 0x52: S.kbd_hid[0] |= (1u << 0); break; /* Cursor Up */
            case 0x4F: S.kbd_hid[0] |= (1u << 1); break; /* Cursor Right */
            case 0x51: S.kbd_hid[0] |= (1u << 2); break; /* Cursor Down */
            case 0x50: S.kbd_hid[1] |= (1u << 0); break; /* Cursor Left */
            case 0x3A: S.kbd_hid[1] |= (1u << 5); break; /* F1 */
            case 0x3B: S.kbd_hid[1] |= (1u << 6); break; /* F2 */
            case 0x3C: S.kbd_hid[0] |= (1u << 5); break; /* F3 */
            }
        }
    }
}

/* ---- File Parsers (.sna, .dsk, .cpr, .bin) ---- */
static int load_sna(const u8 *data, u32 size)
{
    if (size < 0x10100u) return 0;
    if (data[0] != 'M' || data[1] != 'V' || data[2] != ' ' || data[3] != '-' ||
        data[4] != ' ' || data[5] != 'S' || data[6] != 'N' || data[7] != 'A')
        return 0;

    u16 dsz = (u16)data[0x6B] | ((u16)data[0x6C] << 8);
    u32 nb = (dsz >= 128u && size >= 0x20100u) ? 0x20000u : 0x10000u;
    cpc_copy(&WS->ram[0][0], data + 0x100u, nb);

    z80_reset(&S.cpu);
    S.cpu.af.b.l = data[0x11]; S.cpu.af.b.h = data[0x12];
    S.cpu.bc.b.l = data[0x13]; S.cpu.bc.b.h = data[0x14];
    S.cpu.de.b.l = data[0x15]; S.cpu.de.b.h = data[0x16];
    S.cpu.hl.b.l = data[0x17]; S.cpu.hl.b.h = data[0x18];
    S.cpu.r  = data[0x19] & 0x7Fu;
    S.cpu.r7 = data[0x19] & 0x80u;
    S.cpu.i  = data[0x1A];
    S.cpu.iff1 = data[0x1B] & 1u;
    S.cpu.iff2 = data[0x1C] & 1u;
    S.cpu.ix.w = (u16)data[0x1D] | ((u16)data[0x1E] << 8);
    S.cpu.iy.w = (u16)data[0x1F] | ((u16)data[0x20] << 8);
    S.cpu.sp.w = (u16)data[0x21] | ((u16)data[0x22] << 8);
    S.cpu.pc.w = (u16)data[0x23] | ((u16)data[0x24] << 8);
    S.cpu.im   = data[0x25] & 3u;
    S.cpu.af2  = (u16)data[0x26] | ((u16)data[0x27] << 8);
    S.cpu.bc2  = (u16)data[0x28] | ((u16)data[0x29] << 8);
    S.cpu.de2  = (u16)data[0x2A] | ((u16)data[0x2B] << 8);
    S.cpu.hl2  = (u16)data[0x2C] | ((u16)data[0x2D] << 8);

    S.ga_inksel = data[0x2E] & 0x1Fu;
    for (int i = 0; i < 16; i++)
        S.ga_ink[i] = data[0x2F + i] & 0x1Fu;
    S.ga_border  = data[0x3F] & 0x1Fu;
    S.ga_config  = data[0x40] & 0x0Fu;
    S.ga_mode    = S.ga_config & 3u;
    S.ga_ram_cfg = data[0x41] & 7u;

    S.crtc_sel = data[0x42] & 0x1Fu;
    for (int i = 0; i < 18; i++)
        S.crtc_reg[i] = data[0x43 + i] & crtc_mask[i];
    S.ma = S.ma_row_start = S.ma_store = ((u16)S.crtc_reg[12] << 8) | S.crtc_reg[13];
    if (data[0x10] >= 3u) {
        S.h_ctr     = data[0xA9];
        S.v_ctr     = data[0xAB] & 0x7Fu;
        S.r_ctr     = data[0xAC] & 0x1Fu;
        S.hsync_ctr = data[0xAE] & 0x0Fu;
        S.vsync_ctr = data[0xAF] & 0x0Fu;
        S.vs        = data[0xB1] ? 1u : 0u;
        S.hs        = data[0xAE] ? 1u : 0u;
        S.h_de      = (S.h_ctr < S.crtc_reg[1]) ? 1u : 0u;
        S.v_de      = (S.v_ctr < S.crtc_reg[6]) ? 1u : 0u;
        S.ga_intcnt = data[0xB3] & 0x3Fu;
        S.cpu.irq   = data[0xB5] & 1u;
    }
    crtc_cmp_h();
    crtc_cmp_v();
    crtc_cmp_raster();

    S.ga_rom_sel = data[0x55];
    S.ppi_pa     = data[0x56];
    S.ppi_pb     = data[0x57];
    S.ppi_pc     = data[0x58];
    S.ppi_ctrl   = data[0x59];

    S.psg_sel = data[0x5A] & 15u;
    for (int i = 0; i < 16; i++)
        psg_write_reg((u8)i, data[0x5B + i]);

    update_banks();
    return 1;
}

static int parse_dsk(const u8 *data, u32 size)
{
    if (size <= 256u || size > CPC_MAX_DSK) return 0;
    int ext = 0;
    if (data[0] == 'M' && data[1] == 'V' && data[2] == ' ' && data[3] == '-' &&
        data[4] == ' ' && data[5] == 'C' && data[6] == 'P' && data[7] == 'C') {
        ext = 0;
    } else if (data[0] == 'E' && data[1] == 'X' && data[2] == 'T' && data[3] == 'E' &&
               data[4] == 'N' && data[5] == 'D' && data[6] == 'E' && data[7] == 'D') {
        ext = 1;
    } else {
        return 0;
    }

    u8 num_tracks = data[0x30];
    u8 num_sides  = data[0x31];
    if (num_sides == 0 || num_sides > 2 || num_tracks == 0 || num_tracks > 84)
        return 0;

    cpc_copy(WS->dsk_data, data, size);
    S.dsk_size   = size;
    S.dsk_tracks = num_tracks;
    S.dsk_sides  = num_sides;
    cpc_zero(WS->trk, sizeof(WS->trk));

    u32 off = 256u;
    for (u8 t = 0; t < num_tracks; t++) {
        for (u8 s = 0; s < num_sides; s++) {
            u32 tsz = ext ? ((u32)data[0x34 + t * num_sides + s] * 256u)
                          : ((u32)data[0x32] | ((u32)data[0x33] << 8));
            if (tsz == 0) continue;
            if (off + tsz > size) return 0;
            const u8 *ti = &WS->dsk_data[off];
            if (ti[0] != 'T' || ti[1] != 'r' || ti[2] != 'a' || ti[3] != 'c')
                return 0;
            u8 def_n = ti[0x14];
            u8 nsec  = ti[0x15];
            if (nsec > 32u) nsec = 32u;
            WS->trk[s][t].num_secs = nsec;
            u32 soff = off + 256u;
            for (u8 i = 0; i < nsec; i++) {
                const u8 *si = ti + 0x18 + i * 8u;
                struct cpc_dsk_sec *sc = &WS->trk[s][t].sec[i];
                sc->c = si[0]; sc->h = si[1]; sc->r = si[2]; sc->n = si[3];
                sc->st1 = si[4]; sc->st2 = si[5];
                u16 ssz = ext ? ((u16)si[6] | ((u16)si[7] << 8))
                              : (u16)(0x80u << (def_n < 7 ? def_n : 2));
                sc->data_off  = soff;
                sc->data_size = ssz;
                soff += ssz;
            }
            off += tsz;
        }
    }
    S.has_dsk = 1;

    /* Find bootable CP/M directory entry on Track 0 (or Track 2 for System format) */
    u8 dir_trk = 0;
    u8 min_r = WS->trk[0][0].num_secs ? WS->trk[0][0].sec[0].r : 0xC1u;
    if ((min_r & 0xC0u) == 0x40u)       /* System format: 2 reserved tracks */
        dir_trk = 2;

    char best_name[16];
    int best_prio = -1;
    best_name[0] = 0;

    for (u8 r = min_r; r < (u8)(min_r + 4u); r++) {
        int idx = fdc_find_sector(0, dir_trk, dir_trk, 0, r);
        if (idx < 0) continue;
        const struct cpc_dsk_sec *sc = &WS->trk[0][dir_trk].sec[idx];
        for (u16 e = 0; e + 32u <= sc->data_size; e += 32u) {
            const u8 *de = &WS->dsk_data[sc->data_off + e];
            if (de[0] != 0 || de[12] != 0) continue; /* user 0, extent 0 */
            char fn[9], fe[4];
            int fn_l = 0, fe_l = 0;
            for (int k = 0; k < 8; k++) {
                u8 c = de[1 + k] & 0x7Fu;
                if (c > ' ' && c < 0x7Fu) fn[fn_l++] = (char)c;
            }
            fn[fn_l] = 0;
            int sys_hidden = (de[10] & 0x80u) != 0;
            for (int k = 0; k < 3; k++) {
                u8 c = de[9 + k] & 0x7Fu;
                if (c > ' ' && c < 0x7Fu) fe[fe_l++] = (char)c;
            }
            fe[fe_l] = 0;
            if (fn_l == 0) continue;

            int is_bas = (fe[0] == 'B' && fe[1] == 'A' && fe[2] == 'S');
            int is_bin = (fe[0] == 'B' && fe[1] == 'I' && fe[2] == 'N');
            int is_empty = (fe_l == 0);
            if (!is_bas && !is_bin && !is_empty) continue;

            int prio = sys_hidden ? 1 : 5;
            if (is_bas || is_empty) prio += 10;
            if (fn[0] == 'D' && fn[1] == 'I' && fn[2] == 'S' && (fn[3] == 'C' || fn[3] == 'K')) prio += 50;
            else if (fn[0] == 'R' && fn[1] == 'U' && fn[2] == 'N') prio += 40;
            else if (fn[0] == 'M' && fn[1] == 'E' && fn[2] == 'N' && fn[3] == 'U') prio += 35;
            else if (fn[0] == 'G' && fn[1] == 'A' && fn[2] == 'M' && fn[3] == 'E') prio += 30;

            if (prio > best_prio) {
                best_prio = prio;
                char *p = best_name, *end = best_name + 15;
                put_s(&p, end, fn);
            }
        }
    }

    if (best_name[0]) {
        S.boot_delay = 85;              /* Wait ~1.7s for BASIC Ready prompt, then auto-RUN! */
        queue_str("RUN\"");
        queue_str(best_name);
        queue_str("\r");
    } else if ((min_r & 0xC0u) == 0x40u) {
        S.boot_delay = 85;
        queue_str("|CPM\r");
    }
    return 1;
}

static int parse_cpr(const u8 *data, u32 size)
{
    if (size < 24u || data[0] != 'R' || data[1] != 'I' || data[2] != 'F' || data[3] != 'F' ||
        data[8] != 'A' || data[9] != 'M' || data[10] != 'S' || data[11] != '!')
        return 0;

    cpc_zero(WS->cpr_banks, sizeof(WS->cpr_banks));
    u32 pos = 12u;
    int got = 0;
    while (pos + 8u <= size) {
        u32 csz = (u32)data[pos + 4] | ((u32)data[pos + 5] << 8) |
                  ((u32)data[pos + 6] << 16) | ((u32)data[pos + 7] << 24);
        if (data[pos] == 'c' && data[pos + 1] == 'b' &&
            data[pos + 2] >= '0' && data[pos + 2] <= '3' &&
            data[pos + 3] >= '0' && data[pos + 3] <= '9') {
            int bank = (data[pos + 2] - '0') * 10 + (data[pos + 3] - '0');
            if (bank >= 0 && bank < 32 && pos + 8u <= size) {
                u32 cp = csz > 0x4000u ? 0x4000u : csz;
                if (pos + 8u + cp > size) cp = size - (pos + 8u);
                cpc_copy(WS->cpr_banks[bank], data + pos + 8u, cp);
                got++;
            }
        }
        pos += 8u + ((csz + 1u) & ~1u);
    }
    if (!got) return 0;
    S.has_cpr = 1;
    S.cpr_num_banks = (u8)got;
    return 1;
}

void cpc_reset(void)
{
    cpc_zero(&WS->ram[0][0], sizeof(WS->ram));
    cpc_zero(WS->fb, sizeof(WS->fb));
    cpc_zero(WS->line_mode, sizeof(WS->line_mode));

    z80_init(&S.cpu);
    S.cpu.in      = cpc_io_in;
    S.cpu.out     = cpc_io_out;
    S.cpu.irq_ack = cpc_irq_ack;

    S.ga_inksel = 0; S.ga_config = 0; S.ga_border = 0x14;
    for (int i = 0; i < 16; i++) S.ga_ink[i] = 0x14;
    S.ga_mode = 1; S.ga_ram_cfg = 0; S.ga_rom_sel = 0;
    S.ga_hscount = S.ga_intcnt = S.ga_clkcnt = S.ga_sync = S.ga_prev_hs = S.ga_prev_vs = 0;

    S.crt_x = S.crt_y = S.crt_hpos = S.crt_vpos = S.crt_hret = S.crt_vret = S.crt_sync_cnt = 0;
    S.crt_vis = S.crt_sync = S.crt_hblank = S.crt_vblank = 0;

    cpc_zero(S.crtc_reg, sizeof(S.crtc_reg));
    /* Standard CPC power-on CRTC defaults (64 CCLK/line, 312 lines) */
    static const u8 def_crtc[18] = {63, 40, 46, 0x8E, 38, 0, 25, 30, 0, 7, 0, 0, 0x30, 0, 0, 0, 0, 0};
    for (int i = 0; i < 18; i++) S.crtc_reg[i] = def_crtc[i];
    S.crtc_reg[31] = 0xFFu;
    S.h_ctr = S.hsync_ctr = S.v_ctr = S.r_ctr = S.vsync_ctr = 0;
    S.ma = S.ma_row_start = S.ma_store = 0x3000u;
    S.hs = S.vs = 0;
    S.h_de = S.v_de = 1;

    S.ppi_pa = S.ppi_pb = S.ppi_pc = 0;
    S.ppi_ctrl = 0x82u;

    S.psg_sel = S.psg_latch = 0;
    cpc_zero(S.psg_reg, sizeof(S.psg_reg));
    S.psg_lfsr = 1u;
    S.psg_out[0] = S.psg_out[1] = S.psg_out[2] = 0;
    S.psg_phase[0] = S.psg_phase[1] = S.psg_phase[2] = S.psg_nphase = S.psg_ephase = 0;
    S.psg_estep = S.psg_evol = S.psg_ehold = S.psg_eatt = 0;

    cpc_zero(S.kbd_hid, sizeof(S.kbd_hid));
    cpc_zero(S.kbd_joy, sizeof(S.kbd_joy));
    cpc_zero(S.kbd_auto, sizeof(S.kbd_auto));

    S.fdc_phase = FDC_IDLE;
    S.fdc_phys_trk = 0;
    S.fdc_cur_sec = 0;
    S.dsk_motor = 0;

    S.out_w = CPC_W_STD;
    S.out_h = CPC_H_STD;
    update_banks();
}

const char *cpc_load(const u8 *ext_os, const u8 *ext_basic, const u8 *ext_amsdos,
                     u8 *image, u32 size, const char *path)
{
    (void)path;
    cpc_zero(&S, sizeof(S));
    for (int i = 0; i < 32; i++)
        WS->hw_pal[i] = RGB15_CPC(cpc_hw_rgb[i][0], cpc_hw_rgb[i][1], cpc_hw_rgb[i][2]);
    WS->hw_pal[32] = 0;

    cpc_copy(WS->rom_os,     ext_os     ? ext_os     : cpc_rom_os,     0x4000u);
    cpc_copy(WS->rom_basic,  ext_basic  ? ext_basic  : cpc_rom_basic,  0x4000u);
    cpc_copy(WS->rom_amsdos, ext_amsdos ? ext_amsdos : cpc_rom_amsdos, 0x4000u);

    cpc_reset();

    char *p = S.info, *end = S.info + sizeof(S.info) - 1;
    if (!image || size == 0) {
        put_s(&p, end, "Amstrad CPC 6128 (128 KB, Locomotive BASIC 1.1)");
        return 0;
    }

    if (load_sna(image, size)) {
        put_s(&p, end, "Amstrad CPC 6128 snapshot (.sna), ");
        put_u(&p, end, size >> 10);
        put_s(&p, end, " KB");
        return 0;
    }
    if (parse_dsk(image, size)) {
        put_s(&p, end, "Amstrad CPC 6128 floppy (.dsk, ");
        put_u(&p, end, S.dsk_tracks);
        put_s(&p, end, "T/");
        put_u(&p, end, S.dsk_sides);
        put_s(&p, end, "S), ");
        put_u(&p, end, size >> 10);
        put_s(&p, end, " KB");
        return 0;
    }
    if (parse_cpr(image, size)) {
        cpc_reset();
        put_s(&p, end, "Amstrad GX4000 / CPC+ cartridge (.cpr, ");
        put_u(&p, end, S.cpr_num_banks);
        put_s(&p, end, " banks), ");
        put_u(&p, end, size >> 10);
        put_s(&p, end, " KB");
        return 0;
    }
    /* AMSDOS 128-byte header .bin */
    if (size > 128u && size <= 0xC080u) {
        u16 sum = 0;
        for (int i = 0; i < 67; i++) sum = (u16)(sum + image[i]);
        u16 hdr_sum = (u16)image[67] | ((u16)image[68] << 8);
        if (sum == hdr_sum && hdr_sum != 0) {
            u16 load_a  = (u16)image[21] | ((u16)image[22] << 8);
            u16 start_a = (u16)image[26] | ((u16)image[27] << 8);
            u32 len = size - 128u;
            for (u32 i = 0; i < len && (load_a + i) < 0x10000u; i++)
                S.cpu.wr[(load_a + i) >> 10][(load_a + i) & 0x3FFu] = image[128u + i];
            const char *hex = "0123456789ABCDEF";
            char cmd[16] = {'C','A','L','L',' ','&',
                            hex[(start_a >> 12) & 15], hex[(start_a >> 8) & 15],
                            hex[(start_a >> 4) & 15],  hex[start_a & 15], '\r', 0};
            S.boot_delay = 85;
            queue_str(cmd);
            put_s(&p, end, "Amstrad CPC AMSDOS binary (.bin), ");
            put_u(&p, end, size >> 10);
            put_s(&p, end, " KB");
            return 0;
        }
    }
    return "unrecognized Amstrad CPC image (expected .sna, .dsk, .cpr or AMSDOS .bin)";
}

void cpc_frame(u16 pad, u16 *picture)
{
    /* Map gamepad to CPC Joystick 0 (column 9: Up=0, Down=1, Left=2, Right=3, Fire1=4, Fire2=5) + Enter/Space */
    cpc_zero(S.kbd_joy, sizeof(S.kbd_joy));
    if (pad & 0x10u) S.kbd_joy[9] |= 0x01u;
    if (pad & 0x20u) S.kbd_joy[9] |= 0x02u;
    if (pad & 0x40u) S.kbd_joy[9] |= 0x04u;
    if (pad & 0x80u) S.kbd_joy[9] |= 0x08u;
    if (pad & 0x01u) S.kbd_joy[9] |= 0x10u; /* X / OK -> Fire 1 */
    if (pad & 0x02u) S.kbd_joy[9] |= 0x20u; /* Z / 0  -> Fire 2 */
    if (pad & 0x08u) S.kbd_joy[2] |= 0x04u; /* Enter  -> Return */
    if (pad & 0x04u) S.kbd_joy[5] |= 0x80u; /* Select -> Space */

    /* Step auto-type queue (for .dsk / .bin auto-boot and UART typing) */
    cpc_zero(S.kbd_auto, sizeof(S.kbd_auto));
    if (S.boot_delay > 0) {
        S.boot_delay--;
    } else if (S.type_hold > 0) {
        kbd_press_char(S.kbd_auto, S.type_q[S.type_head]);
        if (--S.type_hold == 0) {
            S.type_head = (u8)((S.type_head + 1u) % sizeof(S.type_q));
            S.type_gap = 3;
        }
    } else if (S.type_gap > 0) {
        S.type_gap--;
    } else if (S.type_head != S.type_tail) {
        S.type_hold = 3;
        kbd_press_char(S.kbd_auto, S.type_q[S.type_head]);
    }

    /* Execute 19,968 CCLKs (312 lines * 64 us) with hardware 4T-aligned NOP timing */
    S.cpu.cycles = 0;
    u32 cclk_done = 0;
    while (cclk_done < 19968u) {
        s32 prev = S.cpu.cycles;
        z80_run(&S.cpu, prev + 1);
        S.cpu.cycles = (S.cpu.cycles + 3) & ~3;
        u32 n_cclk = (u32)(S.cpu.cycles - prev) >> 2;
        if (n_cclk == 0) n_cclk = 1;
        for (u32 i = 0; i < n_cclk; i++)
            cclk_step();
        cclk_done += n_cclk;
        if (S.snd_hz) {
            S.snd_acc += n_cclk * S.snd_hz;
            while (S.snd_acc >= 1000000u) {
                S.snd_acc -= 1000000u;
                psg_step_sample(1000000u / S.snd_hz);
            }
        }
    }

    /* Determine whether screen is predominantly Mode 2 (640x200 80-column hi-res) or Mode 0/1 (384x240) */
    int m2_lines = 0;
    for (int y = 36; y < 236; y++)
        if (WS->line_mode[y] == 2u)
            m2_lines++;

    if (m2_lines > 100) {
        S.out_w = CPC_W_HI;
        S.out_h = CPC_H_HI;
        if (picture) {
            for (int y = 0; y < CPC_H_HI; y++) {
                const u8 *src = &WS->fb[(y + 36) * CPC_FB_W + 64];
                u16 *dst = picture + y * CPC_W_HI;
                for (int x = 0; x < CPC_W_HI; x++)
                    dst[x] = WS->hw_pal[src[x]];
            }
        }
    } else {
        S.out_w = CPC_W_STD;
        S.out_h = CPC_H_STD;
        if (picture) {
            for (int y = 0; y < CPC_H_STD; y++) {
                const u8 *src = &WS->fb[(y + 16) * CPC_FB_W];
                u16 *dst = picture + y * CPC_W_STD;
                for (int x = 0; x < CPC_W_STD; x++)
                    dst[x] = WS->hw_pal[src[x * 2]];
            }
        }
    }
}

int cpc_width(void)  { return S.out_w; }
int cpc_height(void) { return S.out_h; }
const char *cpc_info(void) { return S.info; }

u8 *cpc_save_ram(u32 *size, int *battery)
{
    if (S.has_dsk && S.dsk_size > 0) {
        *size = S.dsk_size;
        *battery = 1;
        return WS->dsk_data;
    }
    *size = 0;
    *battery = 0;
    return WS->sav_dummy;
}

int cpc_save_changed(void)
{
    int d = S.dsk_dirty;
    S.dsk_dirty = 0;
    return d;
}

int cpc_jammed(void) { return 0; }

void cpc_audio_rate(u32 hz)
{
    S.snd_hz = (hz >= 8000u && hz <= 192000u) ? hz : 0;
    S.snd_acc = 0;
    S.snd_head = S.snd_count = 0;
}

int cpc_audio(s16 *out, int max)
{
    int n = 0;
    while (n < max && S.snd_count) {
        out[n++] = WS->snd_ring[S.snd_head];
        S.snd_head = (S.snd_head + 1u) % CPC_RING_LEN;
        S.snd_count--;
    }
    return n;
}
